1	//! `leviathan serve --http`: the same tools over the network, for agents on
2	//! other machines and hosted apps.
3	//!
4	//! - `POST /mcp`: MCP Streamable HTTP with JSON responses. The server never
5	//!   pushes, so `GET /mcp` is 405, as the spec allows.
6	//! - `POST /v1/<tool>` and `GET /openapi.json`: plain REST for
7	//!   function-calling frameworks and ChatGPT GPT Actions.
8	//! - `GET /healthz`.
9	//! - OAuth 2.1 endpoints with `--auth oauth` (see `oauth.rs`).
10	//!
11	//! Plain HTTP only: put TLS in front (Caddy, a tunnel) for anything beyond
12	//! localhost or a private network.
13	
14	mod client;
15	
16	use std::io::{Read, Write};
17	use std::net::{SocketAddr, ToSocketAddrs};
18	use std::path::{Path, PathBuf};
19	use std::sync::Arc;
20	use std::thread::JoinHandle;
21	
22	use anyhow::{Context, Result, bail};
23	use base64::Engine;
24	use serde_json::{Value, json};
25	use tiny_http::{Header, Method, Request, Response, Server};
26	
27	pub use client::{TOKEN_ENV, bridge, call_tool, client_token};
28	
29	use crate::mcp::{self, ServerOptions, Session};
30	use crate::oauth::{self, Limit, OAuth, Reply};
31	
32	const MAX_BODY: u64 = 4 << 20;
33	
34	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
35	pub enum AuthMode {
36	    /// A bearer token from the token file.
37	    Token,
38	    /// OAuth 2.1 for hosted apps; the token file's token works too.
39	    OAuth,
40	    /// No auth: loopback binds only.
41	    None,
42	}
43	
44	#[derive(Debug, Clone)]
45	pub struct HttpOptions {
46	    pub server: ServerOptions,
47	    pub addr: String,
48	    pub auth: AuthMode,
49	    pub token_file: PathBuf,
50	    /// The URL clients reach this server at (required for OAuth).
51	    pub public_url: Option<String>,
52	    /// Extra browser origins allowed to call (loopback origins always are).
53	    pub allow_origins: Vec<String>,
54	    pub threads: usize,
55	}
56	
57	struct Shared {
58	    auth: AuthMode,
59	    token: Option<String>,
60	    base_url: String,
61	    allow_origins: Vec<String>,
62	    openapi: String,
63	    oauth: Option<(PathBuf, oauth::Shared)>,
64	}
65	
66	/// A running server: `wait` blocks (the CLI), `stop` shuts it down (tests).
67	pub struct Running {
68	    pub addr: SocketAddr,
69	    /// The MCP endpoint.
70	    pub url: String,
71	    server: Arc<Server>,
72	    shared: Arc<Shared>,
73	    workers: Vec<JoinHandle<()>>,
74	}
75	
76	impl Running {
77	    /// The approval code for a pending OAuth request (what the log prints).
78	    pub fn approval_code(&self, request_id: &str) -> Option<String> {
79	        self.shared.oauth.as_ref()?.1.approval_code(request_id)
80	    }
81	
82	    pub fn wait(self) {
83	        for w in self.workers {
84	            let _ = w.join();
85	        }
86	    }
87	
88	    pub fn stop(self) {
89	        for _ in &self.workers {
90	            self.server.unblock();
91	        }
92	        self.wait();
93	    }
94	}
95	
96	fn is_loopback_host(host: &str) -> bool {
97	    let host = host.trim_start_matches('[').trim_end_matches(']');
98	    host == "localhost" || host.parse::<std::net::IpAddr>().is_ok_and(|ip| ip.is_loopback())
99	}
100	
101	/// The host of `scheme://host[:port]/...`, without the port.
102	fn host_of(url: &str) -> Option<String> {
103	    let (_, rest) = url.split_once("://")?;
104	    let host = rest.split(['/', '?', '#']).next()?;
105	    Some(match host.rsplit_once(':') {
106	        Some((h, p)) if p.chars().all(|c| c.is_ascii_digit()) => h.to_string(),
107	        _ => host.to_string(),
108	    })
109	}
110	
111	/// `scheme://host[:port]` of a URL, lowercased.
112	fn origin_of(url: &str) -> Option<String> {
113	    let (scheme, rest) = url.split_once("://")?;
114	    let host = rest.split(['/', '?', '#']).next()?;
115	    Some(format!("{}://{}", scheme.to_ascii_lowercase(), host.to_ascii_lowercase()))
116	}
117	
118	/// Read the token file, creating it (mode 600) with a fresh token if missing.
119	pub fn ensure_token(path: &Path) -> Result<String> {
120	    if let Ok(text) = std::fs::read_to_string(path) {
121	        let token = text.trim().to_string();
122	        if token.len() < 16 {
123	            bail!("{} holds a token shorter than 16 characters; delete it to generate one", path.display());
124	        }
125	        #[cfg(unix)]
126	        {
127	            use std::os::unix::fs::PermissionsExt;
128	            if let Ok(meta) = std::fs::metadata(path)
129	                && meta.permissions().mode() & 0o077 != 0
130	            {
131	                eprintln!("[leviathan] warning: {} is readable by other users; chmod 600 it", path.display());
132	            }
133	        }
134	        return Ok(token);
135	    }
136	    if let Some(dir) = path.parent().filter(|d| !d.as_os_str().is_empty()) {
137	        std::fs::create_dir_all(dir).with_context(|| format!("create {}", dir.display()))?;
138	    }
139	    let token = format!("lvt_{}", oauth::random_token(32));
140	    let mut opts = std::fs::OpenOptions::new();
141	    opts.write(true).create_new(true);
142	    #[cfg(unix)]
143	    {
144	        use std::os::unix::fs::OpenOptionsExt;
145	        opts.mode(0o600);
146	    }
147	    let mut f = opts.open(path).with_context(|| format!("create {}", path.display()))?;
148	    writeln!(f, "{token}")?;
149	    eprintln!(
150	        "[leviathan] created token file {} (clients send it as `Authorization: Bearer <token>` or set {TOKEN_ENV})",
151	        path.display()
152	    );
153	    Ok(token)
154	}
