199	/// Bind and start the worker threads.
200	pub fn start(opts: HttpOptions) -> Result<Running> {
201	    let addr: SocketAddr = opts
202	        .addr
203	        .to_socket_addrs()
204	        .ok()
205	        .and_then(|mut a| a.next())
206	        .with_context(|| format!("bad --http address {:?}; use host:port", opts.addr))?;
207	    let loopback = addr.ip().is_loopback();
208	    if opts.auth == AuthMode::None && !loopback {
209	        bail!("--auth none is only allowed on a loopback address (127.0.0.1 or ::1), not {addr}");
210	    }
211	    let public_url = opts.public_url.as_deref().map(|u| u.trim_end_matches('/').to_string());
212	    if let Some(u) = &public_url {
213	        let ok = u.starts_with("https://")
214	            || (u.starts_with("http://") && host_of(u).is_some_and(|h| is_loopback_host(&h)));
215	        if !ok {
216	            bail!("--public-url must be https:// (or http://localhost for testing), got {u}");
217	        }
218	    }
219	    if opts.auth == AuthMode::OAuth && public_url.is_none() && !loopback {
220	        bail!("--auth oauth needs --public-url: the https:// URL clients reach this server at");
221	    }
222	    let token = match opts.auth {
223	        AuthMode::None => None,
224	        _ => Some(ensure_token(&opts.token_file)?),
225	    };
226	    let server = Server::http(addr).map_err(|e| anyhow::anyhow!("listen on {addr}: {e}"))?;
227	    let addr = server.server_addr().to_ip().unwrap_or(addr);
228	    let base_url = public_url.unwrap_or_else(|| format!("http://{addr}"));
229	    let oauth = (opts.auth == AuthMode::OAuth).then(|| {
230	        let db = opts.token_file.with_file_name("leviathan-auth.db");
231	        (db, oauth::Shared::new(&base_url))
232	    });
233	    if let Some((db, shared)) = &oauth {
234	        OAuth::open(db, shared.clone())?;
235	    }
236	    for line in Session::new(opts.server.clone()).warm_up() {
237	        eprintln!("[leviathan] http {line}");
238	    }
239	    let shared = Arc::new(Shared {
240	        auth: opts.auth,
241	        token,
242	        openapi: openapi(&opts.server, &base_url).to_string(),
243	        base_url: base_url.clone(),
244	        allow_origins: opts
245	            .allow_origins
246	            .iter()
247	            .map(|o| o.trim_end_matches('/').to_ascii_lowercase())
248	            .collect(),
249	        oauth,
250	    });
251	    let server = Arc::new(server);
252	    let workers = (0..opts.threads.clamp(1, 64))
253	        .map(|_| {
254	            let (server, shared, options) = (Arc::clone(&server), Arc::clone(&shared), opts.server.clone());
255	            std::thread::spawn(move || worker(&server, &shared, options))
256	        })
257	        .collect();
258	    let running_shared = Arc::clone(&shared);
259	    let auth = match opts.auth {
260	        AuthMode::Token => format!("bearer token in {}", opts.token_file.display()),
261	        AuthMode::OAuth => {
262	            format!("OAuth 2.1 (issuer {base_url}) or the token in {}", opts.token_file.display())
263	        }
264	        AuthMode::None => "none (loopback only)".into(),
265	    };
266	    eprintln!("[leviathan] MCP at {base_url}/mcp, REST at {base_url}/v1/<tool>; auth: {auth}");
267	    if !loopback && !base_url.starts_with("https://") {
268	        eprintln!("[leviathan] warning: listening beyond loopback over plain HTTP; put TLS in front of it");
269	    }
270	    Ok(Running { addr, url: format!("{base_url}/mcp"), server, shared: running_shared, workers })
271	}
272	
273	pub fn serve(opts: HttpOptions) -> Result<()> {
274	    start(opts)?.wait();
275	    Ok(())
276	}
277	
278	fn worker(server: &Server, shared: &Shared, options: ServerOptions) {
279	    let mut session = Session::new(options);
280	    let oauth = shared.oauth.as_ref().and_then(|(db, s)| match OAuth::open(db, s.clone()) {
281	        Ok(o) => Some(o),
282	        Err(err) => {
283	            eprintln!("[leviathan] oauth database: {err:#}");
284	            None
285	        }
286	    });
287	    while let Ok(req) = server.recv() {
288	        handle(req, shared, &mut session, oauth.as_ref());
289	    }
290	}
291	
292	fn header<'a>(req: &'a Request, name: &str) -> Option<&'a str> {
293	    req.headers()
294	        .iter()
295	        .find(|h| h.field.as_str().as_str().eq_ignore_ascii_case(name))
296	        .map(|h| h.value.as_str())
297	}
298	
299	fn hdr(name: &str, value: &str) -> Header {
300	    Header::from_bytes(name.as_bytes(), value.as_bytes()).expect("ASCII header")
301	}
302	
303	struct Out {
304	    status: u16,
305	    content_type: &'static str,
306	    body: String,
307	    headers: Vec<(&'static str, String)>,
308	}
309	
310	impl Out {
311	    fn json(status: u16, v: &Value) -> Self {
312	        Out { status, content_type: "application/json", body: v.to_string(), headers: Vec::new() }
313	    }
314	
315	    fn text(status: u16, body: &str) -> Self {
316	        Out { status, content_type: "text/plain; charset=utf-8", body: body.to_string(), headers: Vec::new() }
317	    }
318	
319	    fn empty(status: u16) -> Self {
320	        Self::text(status, "")
321	    }
322	
323	    fn error(status: u16, msg: &str) -> Self {
324	        Self::json(status, &json!({"error": msg}))
325	    }
326	}
327	
328	impl From<Reply> for Out {
329	    fn from(r: Reply) -> Self {
330	        Out { status: r.status, content_type: r.content_type, body: r.body, headers: r.headers }
331	    }
332	}
333	
334	fn origin_allowed(origin: &str, shared: &Shared) -> bool {
335	    let o = origin.trim_end_matches('/').to_ascii_lowercase();
336	    shared.allow_origins.iter().any(|a| a == "*" || *a == o)
337	        || origin_of(&shared.base_url).is_some_and(|b| b == o)
338	        || host_of(&o).is_some_and(|h| is_loopback_host(&h))
339	}
340	
341	/// `Authorization: Bearer …` matches the static token or a live OAuth token.
342	fn authorized(req: &Request, shared: &Shared, oauth: Option<&OAuth>) -> bool {
343	    if shared.auth == AuthMode::None {
344	        return true;
345	    }
346	    let token = header(req, "Authorization").and_then(|v| {
347	        let (scheme, rest) = v.trim().split_once(' ')?;
348	        scheme.eq_ignore_ascii_case("bearer").then(|| rest.trim())
349	    });
350	    let Some(token) = token else { return false };
351	    shared.token.as_deref().is_some_and(|t| oauth::same(t, token))
352	        || oauth.is_some_and(|o| o.check_access(token))
353	}
354	
355	fn unauthorized(oauth: Option<&OAuth>) -> Out {
356	    let mut out = Out::error(401, "missing or invalid bearer token");
357	    let challenge = match oauth {
358	        Some(o) => o.www_authenticate(),
359	        None => "Bearer realm=\"leviathan\"".into(),
360	    };
361	    out.headers.push(("WWW-Authenticate", challenge));
362	    out
363	}
364	
365	fn basic_auth(req: &Request) -> Option<(String, String)> {
366	    let (scheme, rest) = header(req, "Authorization")?.trim().split_once(' ')?;
367	    if !scheme.eq_ignore_ascii_case("basic") {
368	        return None;
369	    }
370	    let decoded = base64::engine::general_purpose::STANDARD.decode(rest.trim()).ok()?;
371	    let text = String::from_utf8(decoded).ok()?;
372	    let (id, secret) = text.split_once(':')?;
373	    Some((oauth::percent_decode(id), oauth::percent_decode(secret)))
374	}
375	
376	fn handle(mut req: Request, shared: &Shared, session: &mut Session, oauth: Option<&OAuth>) {
377	    let origin = header(&req, "Origin").map(str::to_string);
378	    let mut body = String::new();
379	    let unreadable = req.as_reader().take(MAX_BODY + 1).read_to_string(&mut body).is_err();
380	    let out = if origin.as_deref().is_some_and(|o| !origin_allowed(o, shared)) {
381	        Out::error(403, "origin not allowed (see --allow-origin)")
382	    } else if unreadable || body.len() as u64 > MAX_BODY {
383	        Out::error(413, "request body too large or not UTF-8")
384	    } else {
385	        route(&req, &body, shared, session, oauth)
386	    };
387	    let mut resp = Response::from_string(out.body)
388	        .with_status_code(out.status)
389	        .with_header(hdr("Content-Type", out.content_type));
390	    for (k, v) in &out.headers {
391	        resp = resp.with_header(hdr(k, v));
392	    }
393	    if let Some(o) = origin.filter(|o| origin_allowed(o, shared)) {
394	        resp = resp
395	            .with_header(hdr("Access-Control-Allow-Origin", &o))
396	            .with_header(hdr("Vary", "Origin"))
397	            .with_header(hdr("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS"))
398	            .with_header(hdr(
399	                "Access-Control-Allow-Headers",
400	                "authorization, content-type, accept, mcp-session-id, mcp-protocol-version, last-event-id",
401	            ))
402	            .with_header(hdr("Access-Control-Expose-Headers", "mcp-session-id, www-authenticate"));
403	    }
404	    let _ = req.respond(resp);
405	}
406	
407	/// Who is asking, for OAuth rate limits: the peer address, or the address a
408	/// proxy on this machine (Caddy, cloudflared, tailscale) appended last to
409	/// `X-Forwarded-For`. IPv6 counts per /64.
410	fn caller(req: &Request) -> String {
411	    let peer = req.remote_addr().map(|a| a.ip());
412	    let forwarded =
413	        || header(req, "X-Forwarded-For")?.rsplit(',').next()?.trim().parse::<std::net::IpAddr>().ok();
414	    let ip = match peer {
415	        Some(ip) if ip.is_loopback() => forwarded().unwrap_or(ip),
416	        Some(ip) => ip,
417	        None => return "unknown".into(),
418	    };
419	    match ip {
420	        std::net::IpAddr::V6(v6) if v6.to_ipv4_mapped().is_none() => {
421	            let s = v6.segments();
422	            format!("{:x}:{:x}:{:x}:{:x}::/64", s[0], s[1], s[2], s[3])
423	        }
424	        std::net::IpAddr::V6(v6) => v6.to_ipv4_mapped().expect("checked").to_string(),
425	        v4 => v4.to_string(),
426	    }
427	}
428	
429	fn oauth_only(oauth: Option<&OAuth>, f: impl FnOnce(&OAuth) -> Reply) -> Out {
430	    match oauth {
431	        Some(o) => f(o).into(),
432	        None => Out::error(404, "OAuth is off (start the server with --auth oauth)"),
433	    }
434	}
435	
436	fn route(req: &Request, body: &str, shared: &Shared, session: &mut Session, oauth: Option<&OAuth>) -> Out {
437	    let url = req.url().to_string();
438	    let (path, query) = url.split_once('?').unwrap_or((&url, ""));
439	    let path = if path.len() > 1 { path.trim_end_matches('/') } else { path };
440	    let method = req.method().clone();
441	    let protected = path == "/mcp" || path.starts_with("/v1/");
442	    if protected && method != Method::Options && !authorized(req, shared, oauth) {
443	        return unauthorized(oauth);
444	    }
445	    match (&method, path) {
446	        (Method::Options, _) => Out::empty(204),
447	        (Method::Get, "/") => Out::text(
448	            200,
449	            "Leviathan: MCP at POST /mcp, REST at POST /v1/<tool>, schema at GET /openapi.json\n",
450	        ),
451	        (Method::Get, "/healthz") => {
452	            Out::json(200, &json!({"ok": true, "version": env!("CARGO_PKG_VERSION")}))
453	        }
454	        (Method::Get, "/openapi.json") => Out {
455	            status: 200,
456	            content_type: "application/json",
457	            body: shared.openapi.clone(),
458	            headers: Vec::new(),
459	        },
460	        (Method::Get, p) if p.starts_with("/.well-known/oauth-protected-resource") => {
461	            oauth_only(oauth, |o| Reply::json(200, o.protected_resource_metadata()))
462	        }
463	        (Method::Get, p)
464	            if p.starts_with("/.well-known/oauth-authorization-server")
465	                || p.starts_with("/.well-known/openid-configuration") =>
466	        {
467	            oauth_only(oauth, |o| Reply::json(200, o.authorization_server_metadata()))
468	        }
469	        (Method::Post, "/oauth/register") => oauth_only(oauth, |o| {
470	            o.limited(Limit::Register, &caller(req)).unwrap_or_else(|| o.register(body))
471	        }),
472	        (Method::Get, "/oauth/authorize") => oauth_only(oauth, |o| {
473	            let who = caller(req);
474	            o.limited(Limit::Authorize, &who)
475	                .unwrap_or_else(|| o.authorize_page(&oauth::parse_form(query), &who))
476	        }),
477	        (Method::Post, "/oauth/authorize") => oauth_only(oauth, |o| {
478	            o.limited(Limit::Approve, &caller(req))
479	                .unwrap_or_else(|| o.authorize_submit(&oauth::parse_form(body)))
480	        }),
481	        (Method::Post, "/oauth/token") => oauth_only(oauth, |o| {
482	            o.limited(Limit::Token, &caller(req))
483	                .unwrap_or_else(|| o.token(&oauth::parse_form(body), basic_auth(req)))
484	        }),
485	        (Method::Post, "/mcp") => {
486	            if let Some(v) = header(req, "MCP-Protocol-Version")
487	                && !mcp::PROTOCOL_VERSIONS.contains(&v.trim())
488	            {
489	                return Out::json(
490	                    400,
491	                    &json!({"jsonrpc": "2.0", "id": null, "error": {"code": -32600, "message": format!("unsupported MCP-Protocol-Version {v}")}}),
492	                );
493	            }
494	            match session.handle_body(body) {
495	                Some(reply) => Out::json(200, &reply),
496	                None => Out::empty(202),
497	            }
498	        }
499	        (Method::Get | Method::Delete, "/mcp") => {
500	            let mut out = Out::error(405, "this server answers POST /mcp only");
501	            out.headers.push(("Allow", "POST".into()));
502	            out
503	        }
504	        (Method::Post, p) if p.starts_with("/v1/") => rest(&p[4..], query, body, session),
505	        _ => Out::error(404, "not found"),
506	    }
507	}
508	
509	/// `POST /v1/<tool>`: JSON arguments in, the tool's JSON out (`?format=text`
510	/// for the agent-facing text).
511	fn rest(tool: &str, query: &str, body: &str, session: &mut Session) -> Out {
512	    let mut args = if body.trim().is_empty() {
513	        json!({})
514	    } else {
515	        match serde_json::from_str::<Value>(body) {
516	            Ok(v @ Value::Object(_)) => v,
517	            _ => return Out::error(400, "the body must be a JSON object of tool arguments"),
518	        }
519	    };
520	    let text_out = oauth::parse_form(query).get("format").map(String::as_str) == Some("text");
521	    if !text_out {
522	        args["format"] = "json".into();
523	    }
524	    match session.call(tool, &args) {
525	        Ok(s) if text_out => Out::text(200, &s),
526	        Ok(s) => match serde_json::from_str::<Value>(&s) {
527	            Ok(v) => Out::json(200, &v),
528	            Err(_) => Out::json(200, &json!({"text": s})),
529	        },
530	        Err(err) => {
531	            let msg = format!("{err:#}");
532	            Out::error(if msg.starts_with("unknown tool") { 404 } else { 400 }, &msg)
533	        }
534	    }
535	}
536

